def price(n): return f'{n:,}'.replace(',',' ')+' ₽'
def phone(x):
 id,brand,name,tag,cost,mem,screen,cam,chip,color,cname=x
 return f'''<svg viewBox="0 0 300 300" role="img" aria-label="{name}, {cname}"><defs><linearGradient id="g-{id}" x2="1" y2="1"><stop stop-color="{color}"/><stop offset="1" stop-color="#e4e2dc"/></linearGradient><filter id="s-{id}"><feDropShadow dx="0" dy="12" stdDeviation="9" flood-opacity=".13"/></filter></defs><g filter="url(#s-{id})" transform="rotate(-10 150 150)"><rect x="78" y="23" width="137" height="250" rx="27" fill="url(#g-{id})" stroke="#ffffff" stroke-width="2"/><rect x="82" y="27" width="129" height="242" rx="24" fill="none" stroke="#555" stroke-opacity=".22"/><rect x="89" y="37" width="76" height="81" rx="19" fill="{color}" stroke="#fff" stroke-opacity=".4"/><g fill="#192126" stroke="#6a7274" stroke-width="4"><circle cx="109" cy="58" r="14"/><circle cx="143" cy="80" r="14"/><circle cx="109" cy="99" r="14"/></g><g fill="#40505d"><circle cx="109" cy="58" r="5"/><circle cx="143" cy="80" r="5"/><circle cx="109" cy="99" r="5"/></g><circle cx="145" cy="47" r="5" fill="#f6eee0"/><text x="147" y="183" text-anchor="middle" fill="#3e4646" opacity=".5" font-size="12" font-family="Arial">{brand}</text></g></svg>'''
header='<header><a class="logo" href="index.html"><span class="mark">ф</span> флагман<span class="dot">.</span></a><a class="nav" href="index.html">Смартфоны <span>08</span></a><span class="test">Тестовая витрина</span></header>'
footer='<footer><a class="logo" href="index.html">флагман.</a><span>Демонстрационный каталог · Цены условные</span><span>2026</span></footer>'
def page(title,body):return f'''<!doctype html><html lang="ru"><head><meta name="robots" content="noindex, nofollow"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Флагман</title><meta name="description" content="Статическая тестовая витрина флагманских смартфонов"><link rel="stylesheet" href="style.css"></head><body>{header}<main>{body}</main>{footer}</body></html>'''
cards=''
for pos,x in enumerate(products,1):
 id,brand,name,tag,cost,mem,screen,cam,chip,color,cname=x
 cards+=f'''<article class="card" id="product-{id}" data-product-id="{id}" data-product-name="{name}" data-product-price="{cost}" data-list-id="flagships" data-position="{pos}"><a class="product-link" href="{id}.html"><div class="picture"><span class="tag">{mem}</span>{phone(x)}<span class="arrow">↗</span></div><div class="brand">{brand}</div><h2>{name}</h2><p class="short">{screen} · {mem} · {cam}</p><div class="card-bottom"><strong>{price(cost)}</strong><span class="details">Подробнее <span>→</span></span></div></a></article>'''
 body=f'''<div class="breadcrumb"><a href="index.html">Смартфоны</a> <span>/</span> {name}</div><section class="product" data-product-id="{id}" data-product-name="{name}" data-product-price="{cost}" data-page-type="product"><div class="hero-phone">{phone(x)}<span class="image-note">Иллюстрация товара</span></div><div class="product-info"><span class="eyebrow">{brand} / ФЛАГМАНСКАЯ СЕРИЯ</span><h1>{name}</h1><p class="lead">{tag}</p><div class="available"><span></span> В наличии · Демо-товар</div><div class="variant"><span class="label">Цвет</span><span><i style="background:{color}"></i>{cname}</span></div><div class="variant"><span class="label">Память</span><span class="memory">{mem}</span></div><div class="price">{price(cost)}</div><p class="demo-note">Тестовый товар. Оформление заказа недоступно.</p><a class="back" href="index.html">← Вернуться в каталог</a></div></section><section class="specs"><div><span class="eyebrow">ВСЁ САМОЕ ВАЖНОЕ</span><h2>Характеристики</h2></div><dl><div><dt>Экран</dt><dd>{screen} OLED</dd></div><div><dt>Процессор</dt><dd>{chip}</dd></div><div><dt>Основная камера</dt><dd>{cam}</dd></div><div><dt>Встроенная память</dt><dd>{mem}</dd></div></dl></section>'''
 (p/f'{id}.html').write_text(page(name,body))
(p/'index.html').write_text(page('Смартфоны',f'''<section class="intro"><div><span class="eyebrow">ТЕХНОЛОГИИ В ЛУЧШЕЙ ФОРМЕ</span><h1>Флагманы.<br><span>Всё лучшее — здесь.</span></h1><p>Восемь смартфонов, которые задают стандарт.<br>Выберите свой и узнайте больше.</p></div><div class="intro-aside"><span class="orbit">✳</span><span>Большие возможности.<br>В каждой детали.</span></div></section><section class="catalog"><div class="catalog-title"><h2>Смартфоны <span>8</span></h2><span>Подборка флагманов</span></div><div class="grid">{cards}</div></section>'''))
